/**
 * Reads the country borders from the countries.geojson resource file
 */
public static List<CustomArea> readCountries() // PATH: Test should invoke the next ObjectMapper.registerModule(...) [step in execution path]
{
    ObjectMapper objectMapper = new ObjectMapper();
    objectMapper.registerModule(new JtsModule());
    Set<String> enumSet = new HashSet<>(Country.values().length * 2);
    for (Country c : Country.values()) {
        if (c == Country.MISSING) {
            continue;
        }
        if (c.getStates().isEmpty()) {
            enumSet.add(c.getAlpha2());
        } else {
            for (State s : c.getStates()) {
                enumSet.add(s.getStateCode());
            }
        }
    }
    try (Reader reader = new InputStreamReader(GHUtility.class.getResourceAsStream("/com/graphhopper/countries/countries.geojson"), StandardCharsets.UTF_8)) {
        JsonFeatureCollection jsonFeatureCollection = objectMapper.readValue(reader, JsonFeatureCollection.class);
        return // exclude areas not in the list of Country enums like FX => Metropolitan France
        jsonFeatureCollection.getFeatures().stream().filter(customArea -> enumSet.contains(getIdOrPropertiesId(customArea))).map(f -> {
            CustomArea ca = CustomArea.fromJsonFeature(f);
            // the Feature does not include "id" but we expect it
            if (f.getId() == null) {
                f.setId(getIdOrPropertiesId(f));
            }
            ca.getProperties().put(ISO_3166_2, f.getId());
            return ca;
        }).collect(Collectors.toList());
    } catch (IOException e) {
        throw new UncheckedIOException(e);
    }
}

