    try {
        reader.readGraph();
    } catch (IOException ex) {
        throw new RuntimeException("Cannot read file " + getOSMFile(), ex);
    }
    DateFormat f = createFormatter();
    properties.put("datareader.import.date", f.format(new Date()));
